function createTeam(name) {
  return { name, scores: [] };
}

function cloneTeam(team) {
  return Object.assign({}, team);
}

function addScore(team, score) {
  team.scores.push(score);
}

const teamA = createTeam("A");
const teamB = cloneTeam(teamA);
addScore(teamA, 10);
console.log(teamB.scores);
